import Foundation
import AppKit
import WebKit

@MainActor func runSelfTests() {
    var checks=0
    func require(_ condition:@autoclosure()->Bool,_ label:String) { checks+=1;if !condition() { print("FAIL: \(label)"); exit(1) } }
    runMailOriginalHTMLTests { require($0, $1) }
    let a = MailAccount(id:"one",name:"工作",region:"global"), b = MailAccount(id:"two",name:"个人",region:"global")
    require(a.dataIdentifier != b.dataIdentifier,"account storage isolation")
    require(a.dataIdentifier == MailAccount(id:"one",name:"Renamed",region:"global").dataIdentifier,"rename retains session")
    require(Trust.mail(URL(string:"https://mail.zoho.com/zm/")),"mail host")
    require(!Trust.mail(URL(string:"https://mail.zoho.com.evil.example/")),"lookalike rejected")
    require(!Trust.mail(URL(string:"https://user:password@mail.zoho.com/")),"credential URL rejected")
    require(!Trust.outside(URL(string:"javascript:alert(1)")!),"executable URL rejected")
    require(!Trust.outside(URL(string:"file:///etc/passwd")!),"local URL rejected")
    require(Trust.inside(URL(string:"https://accounts.zoho.com/signin")),"login allowed")
    require(Trust.numericID("900719925474099303") == "900719925474099303","large IDs retained")
    require(Trust.numericID("1/../../") == nil,"path injection rejected")
    require(Trust.numericID(true) == nil,"boolean IDs rejected")
    let origin = Region.find("global")!.origin
    let row:[String:Any] = ["messageId":"900719925474099303","folderId":"500","receivedTime":"10000","subject":"Real subject","sender":"Sender","status":"0"]
    let message = MailMessage.parse(row,accountID:a.id,remoteID:"100",folderID:"500",origin:origin)!
    require(message.unread && (try? MailAPI().messageURL(message,suffix:"content").absoluteString) == "https://mail.zoho.com/api/accounts/100/folders/500/messages/900719925474099303/content","direct body request retains account folder and message identity")
    require(MailMessage.parse(row,accountID:a.id,remoteID:"100",folderID:"501",origin:origin) == nil,"only Inbox included")
    let cookie = HTTPCookie(properties:[.domain:".zoho.com",.path:"/api",.name:"sample",.value:"test",.secure:"TRUE"])!
    require(MailAPI.cookieHeader([cookie],for:origin.appendingPathComponent("api/accounts")) == "sample=test","account cookies used for own host")
    require(MailAPI.cookieHeader([cookie],for:URL(string:"https://evilzoho.com/api/accounts")!).isEmpty,"cookie domain boundary")
    require(MailAPI.cookieHeader([cookie],for:origin.appendingPathComponent("apix" )).isEmpty,"cookie path boundary")
    let temp = FileManager.default.temporaryDirectory.appendingPathComponent("mail-native-test-\(UUID().uuidString)")
    let prefs = PreferenceFile(directory:temp); prefs.value.accounts = [a,b]
    prefs.value.autoBccMyself = true
    prefs.value.defaultBccAddress = "archive@example.test"
    prefs.value.defaultBccByAccount = [a.id: "account-archive@example.test"]
    prefs.save()
    let loadedPrefs = PreferenceFile(directory:temp).value
    require(loadedPrefs.accounts.count == 2,"native settings persist")
    require(loadedPrefs.autoBccMyself && loadedPrefs.defaultBccAddress == "archive@example.test" && loadedPrefs.defaultBccByAccount[a.id] == "account-archive@example.test", "default bcc preferences persist and reload")
    let other=MailMessage.parse(row,accountID:b.id,remoteID:"100",folderID:"500",origin:origin)!
    let cached=MailCache(directory:temp)
    cached.store([message],account:a.id,replace:true);cached.store([other],account:b.id,replace:true)
    require(cached.messages(accounts:[a.id,b.id]).count == 2,"identical message IDs in different accounts remain separate")
    require(cached.messages(accounts:[b.id]).first?.accountID == b.id,"cache filters signed-in account identities")
    let detail=MailDetail(message:message,from:"Sender <sender@example.test>",to:"own@example.test, other@example.test",cc:"other@example.test, cc@example.test",replyTo:"reply@example.test",html:"<p>Cached body</p>",attachments:[],inline:[])
    cached.store(detail)
    require(cached.detail(message)?.html == detail.html && cached.detail(other) == nil,"body cache cannot cross account boundary")
    require(MailCache(directory:temp).detail(message)?.message.key == message.key,"body cache persists across reopen")
    cached.store([],account:a.id,replace:true)
    require(cached.messages(accounts:[a.id,b.id]).count == 1,"refresh replaces only the selected account Inbox cache")
    let addresses=MailAddresses.replyAll(detail,own:"own@example.test")
    require(addresses.to == "reply@example.test" && addresses.cc == "other@example.test, cc@example.test","reply-all uses reply-to and excludes own mailbox and duplicate recipients")
    require(MailAddresses.headerAddress("Reply-To",in:["rEpLy-To":["Customer <client@example.test>"]]) == "client@example.test", "inquiry RFC Reply-To supports case-insensitive array headers")
    require(MailAddresses.headerAddress("Reply-To",in:["Reply-To":"client@example.test"]) == "client@example.test", "Reply-To supports string header values")
    let inquiry = MailDetail(message:message,from:"Website <forms@example.test>",to:"own@example.test",cc:"",replyTo:"client@example.test",html:"<p>Other address: unrelated@example.test</p>",attachments:[],inline:[])
    require(MailAddresses.reply(inquiry,own:["own@example.test"]).to == "client@example.test", "inquiry reply goes to customer Reply-To, not form sender or body addresses")
    let selfForm = MailDetail(message:message,from:"own@example.test",to:"own@example.test",cc:"",replyTo:"client@example.test",html:"",attachments:[],inline:[])
    require(MailAddresses.reply(selfForm,own:["own@example.test"]).to == "client@example.test", "self-sent website inquiry still honors external customer Reply-To")
    let ordinary = MailDetail(message:message,from:"client@example.test",to:"own@example.test",cc:"",replyTo:" ",html:"",attachments:[],inline:[])
    require(ordinary.replyAddress == "client@example.test", "empty whitespace Reply-To falls back to From")
    let sent = MailDetail(message:message,from:"Alias <sales@example.test>",to:"Client <client@example.test>, OWN@example.test",cc:"other@example.test, sales@example.test",replyTo:"sales@example.test",html:"",attachments:[],inline:[])
    require(MailAddresses.reply(sent,own:["own@example.test","sales@example.test"]).to == "client@example.test", "reply to sent message addresses customer rather than own alias")
    let sentAll = MailAddresses.reply(sent,own:["own@example.test","sales@example.test"],all:true)
    require(sentAll.to == "client@example.test" && sentAll.cc == "other@example.test", "sent reply-all excludes all own identities")
    let receivedAll = MailAddresses.reply(detail,own:["own@example.test","other@example.test"],all:true)
    require(receivedAll.to == "reply@example.test" && receivedAll.cc == "cc@example.test", "received reply-all excludes own aliases and deduplicates")
    require((try? JSONDecoder().decode(MailDetail.self,from:JSONEncoder().encode(inquiry)))?.replyHeadersChecked == nil, "legacy details without header verification remain readable")
    let fragment=MailHTML.document("<html><head><base href='https://evil.test'><script>alert(1)</script></head><body><p onclick='evil()'>Mail</p><iframe src='https://evil.test'></iframe><a href='javascript:alert(1)'>bad</a><img src='https://evil.test/tracker'><img src='file:///etc/passwd'><img src='cid:photo'></body></html>",inline:[.init(id:"123",name:"image.png",size:1,cid:"photo")])
    require(!fragment.contains("<script") && !fragment.contains("onclick=") && !fragment.contains("<iframe") && !fragment.contains("javascript:"),"email HTML drops executable markup")
    require(!fragment.contains("https://evil.test") && !fragment.contains("file:///"),"email HTML blocks automatic external and local resource loads")
    require(fragment.contains("mail-inline://message/123"),"inline image refers to typed attachment identity only")
    require(fragment.contains("script-src 'none'") && fragment.contains("form-action 'none'"),"body CSP blocks scripts forms and network requests")
    require(MailHTML.document("<img src='https://images.example.test/p.png'>",images:true).contains("src=\"https://images.example.test/p.png\""),"external images require explicit reader action")
    require(MailHTML.plainText("<p>Hello</p><p>World</p>").contains("Hello"),"reply quotation uses message body text")
    require(MailHTML.document("<meta charset='windows-1252'><p>中文 café français</p>").contains("中文 café français") && MailHTML.plainText("<p>中文 café français</p>").contains("中文 café français"),"Unicode survives HTML fragments and stale original charset declarations")
    require(!MailHTML.plainText("<head><style>.private {color:red}</style></head><p>正文</p><script>alert(1)</script>").contains("color:red") && MailHTML.plainText("<head><style>.private {color:red}</style></head><p>正文</p>").contains("正文"),"reply text excludes original CSS and script contents")
    let inbox=MailFolder(id:"500",name:"Inbox",path:"/Inbox",type:"Inbox"),drafts=MailFolder(id:"501",name:"Drafts",path:"/Drafts",type:"Drafts")
    require(inbox.systemName=="Inbox" && MailFolder(id:"502",name:"Vendor",path:"/Vendor",type:"Inbox").systemName==nil,"custom Inbox-type folder is not system Inbox")
    let context=MailboxSession(accountID:a.id,remoteID:"100",email:"own@example.test",origin:origin,folders:[inbox,drafts],addresses:["own@example.test"])
    cached.store(context)
    require(MailCache(directory:temp).contexts(accounts:[a.id]).first?.folders.count==2 && cached.contexts(accounts:[b.id]).isEmpty,"folder catalogs persist and respect account boundary")
    var draftRow=row;draftRow["folderId"]="501";draftRow["messageId"]="700";draftRow["status"]="unread";draftRow["threadId"]="0";draftRow.removeValue(forKey:"receivedTime");draftRow["receivedtime"]="20000"
    let draftMessage=MailMessage.parse(draftRow,accountID:a.id,remoteID:"100",folderID:"501",origin:origin)!
    require(draftMessage.unread && draftMessage.threadID==nil && draftMessage.date.timeIntervalSince1970==20,"alternate timestamp and unread encoding parsed without grouping zero thread")
    cached.store([message,draftMessage],account:a.id,replace:true);cached.store([],account:a.id,replace:true,folderID:"500")
    require(cached.messages(accounts:[a.id]).map{$0.id}==["700"] && cached.detail(message)?.html==detail.html,"folder refresh preserves other folders and body cache")
    require((try? MailAction.move("501").payload([message])["destfolderId"] as? String)=="501","move payload keeps selected source destination ID")
    require((try? MailAction.read.payload([message])["messageId"] as? [String])==[message.id],"action preserves IDs larger than JavaScript safe integer")
    require((try? MailAction.read.payload([message,other]))==nil,"batch action rejects mixed account identities")
    require((try? MailAction.move("../../").payload([message]))==nil && (try? MailAction.trash.payload([message]))==nil,"move traversal and unresolved Trash rejected")
    require((try? MailAction.flag("not-a-flag").payload([message]))==nil,"unknown flag rejected")
    var threaded=message;threaded.threadID="999";var older=message;older=MailMessage(accountID:a.id,remoteID:"100",folderID:"500",id:"701",origin:origin,subject:"older",sender:"Sender",preview:"",date:Date(timeIntervalSince1970:1),attachment:false,unread:false,threadID:"999")
    var foreign=other;foreign.threadID="999"
    let grouped=MailMessage.conversations([threaded,older,foreign])
    require(grouped.count==2 && grouped.first(where:{$0.accountID==a.id})?.threadCount==2,"conversation grouping merges only same-account thread and keeps newest first")
    let store=DraftStore(directory:temp)
    var local=MailDraft(accountID:a.id,from:"own@example.test",mode:"reply",source:detail)
    local.bcc="hidden@example.test";local.body="恢复正文";local.rtf=Data("rtf-test".utf8);local.cloudUncertain=true;local.state="uncertain";local.scheduleType=2;local.receipt=true
    let original=temp.appendingPathComponent("draft-file.txt");try! Data("original".utf8).write(to:original)
    let copy=try! store.importFile(original,id:local.id);local.files=[copy.path];try! store.save(local)
    try! Data("changed".utf8).write(to:original)
    let restored=DraftStore(directory:temp).all(accounts:[a.id]).first!
    require(restored.bcc==local.bcc && restored.rtf==local.rtf && restored.source?.message.key==message.key,"draft restores Bcc rich text and source account identity")
    require(restored.state=="uncertain" && restored.cloudUncertain && restored.receipt && restored.scheduleType==2,"uncertain send and cloud state survive process restart")
    require((try? String(contentsOf:store.files(restored).first!,encoding:.utf8))=="original","draft attachments copied into managed storage independently of originals")
    require(store.all(accounts:[b.id]).isEmpty && (try? store.folder("../../"))==nil,"draft account and directory traversal boundary")
    local.files=[original.path];require(store.files(local).isEmpty,"restoration excludes external paths")
    let permissions=(try! FileManager.default.attributesOfItem(atPath:try! store.folder(restored.id).appendingPathComponent("draft.json").path))[.posixPermissions] as? NSNumber
    require(permissions?.intValue==0o600,"draft contents are owner-only")
    require(MailAddresses.validated("Name <first@example.test>, second@example.test")?.count==2 && MailAddresses.validated("first@example.test\r\nBcc: other@example.test")==nil,"recipient validation rejects header injection")
    var pinned=message;pinned.pinned=true;pinned.snoozedUntil=Date(timeIntervalSince1970:5000);pinned.labels=["77"]
    require((try? MailAction.pin(true).payload([pinned])["mode"] as? String)=="pin","pin action mode")
    require((try? MailAction.snooze(Date().addingTimeInterval(3600)).payload([pinned])["snoozeTime"] as? Int) != nil,"snooze requires future time and carries it")
    require((try? MailAction.snooze(Date(timeIntervalSince1970:1)).payload([pinned]))==nil,"past snooze rejected")
    require((try? MailAction.label("77",true).payload([pinned])["labelId"] as? String)=="77","label id travels in payload")
    require((try? MailAction.label("../../",true).payload([pinned]))==nil,"label traversal rejected")
    require(MailLabel(id:"1",name:"设计",color:"#5B6CFF").tintIndex >= 0,"label color mapping")
    require(MailHTML.document("<p>x</p>",dark:true).contains("color-scheme:dark") && MailHTML.document("<p>x</p>",dark:true).contains("background:transparent"),"dark body palette keeps transparent background")
    let darkCard = MailHTML.document("<div style='background-color:#ffffff;color:#111111;border-color:#eeeeee'>x</div>", dark: true)
    require(!darkCard.contains("#ffffff") && !darkCard.contains("#111111") && !darkCard.contains("#eeeeee"),"dark mode remaps light surfaces, dark text and light borders")
    require(darkCard.contains("background-color:#") && darkCard.contains("color:#"),"dark mode keeps mapped declarations")
    require(MailHTML.mapDarkBackground("#ffffff") == "#242424", "white email backgrounds map to neutral dark grey without blue tint")
    require(MailHTML.mapDarkBackground("#f5f5f5") == "#2a2a2a", "pale grey form labels remain raised above the dark email background")
    require(MailHTML.mapDarkBackground("#202020") == nil && MailHTML.mapDarkBackground("transparent") == nil, "authored dark and transparent backgrounds are retained")
    let tableDocument = MailHTML.document("<table border='1' cellpadding='8' cellspacing='0'><tr><td>Cell</td></tr></table>")
    require(tableDocument.contains("border=\"1\"") && tableDocument.contains("cellpadding=\"8\"") && tableDocument.contains("cellspacing=\"0\""), "safe numeric table borders and spacing survive HTML import")
    require(!MailHTML.document("<table cellpadding='999999' border='javascript:alert(1)'><tr><td>x</td></tr></table>").contains("cellpadding="), "unbounded table presentation attributes are dropped")
    let lightCard = MailHTML.document("<div style='background-color:#ffffff;color:#111111'>x</div>", dark: false)
    require(lightCard.contains("#ffffff") && lightCard.contains("#111111"),"light mode preserves authored colours")
    let paper = MailHTML.document("<p>x</p>", paper: true)
    require(paper.contains("background:#ffffff") && paper.contains("color:#1c1d21"),"paper mode gives the email an opaque light page")
    require(MailHTML.components("rgb(255,255,255)") != nil && MailHTML.components("#eee") != nil && MailHTML.components("transparent") == nil,"colour parser handles hex, rgb and transparent")
    let legacy = Data("{\"width\":1200,\"height\":800,\"accounts\":[]}".utf8)
    let decoded = try! JSONDecoder().decode(NativePreferences.self, from: legacy)
    require(decoded.width==1200 && decoded.listWidth==392 && decoded.notificationsEnabled==false,"old preferences decode with new defaults")
    let outbox = OutboxStore(directory: temp.appendingPathComponent("outbox"))
    var item = OutboxItem(accountID:a.id, from:"own@example.test", to:"dest@example.test", subject:"queued")
    require((try? JSONDecoder().decode(OutboxItem.self, from: JSONEncoder().encode(item)))?.archiveAfterSend == nil, "legacy outbox entries do not request archive")
    item.archiveAfterSend = message
    item.scheduledAt = Date().addingTimeInterval(600)
    let attachment = temp.appendingPathComponent("queue.txt"); try! Data("queued-bytes".utf8).write(to: attachment)
    let imported = try! outbox.importAttachment(attachment, id: item.id)
    item.state = "queued"
    outbox.save(item)
    let reopened = OutboxStore(directory: temp.appendingPathComponent("outbox"))
    require(reopened.all().first?.subject == "queued" && reopened.attachments(item.id).count == 1,"outbox persists scheduled item with managed attachment")
    require(reopened.all().first?.archiveAfterSend?.key == message.key, "send-and-archive retains original account folder and message identity in durable queue")
    require(FileManager.default.fileExists(atPath: imported) && reopened.all().first?.scheduledAt != nil,"queued attachment copy survives reopening")
    reopened.remove(item.id)
    require(OutboxStore(directory: temp.appendingPathComponent("outbox")).all().isEmpty,"outbox removal is durable")
    _ = NSApplication.shared
    let pendingEditor = EditorHandle()
    pendingEditor.setText("Restored draft")
    require(pendingEditor.plainText() == "Restored draft" && pendingEditor.rtfData() != nil, "editor retains body and serializes drafts before NSTextView attachment")
    let attachedEditor = NSTextView()
    pendingEditor.attach(attachedEditor)
    require(attachedEditor.string == "Restored draft" && attachedEditor.selectedRange().location == 0, "editor attachment replays initial document with caret at reply start")
    let defaultFontEditor = EditorHandle()
    defaultFontEditor.loadHTML("<p>Plain reply</p>")
    let fontView = NSTextView()
    defaultFontEditor.attach(fontView)
    let importedFont = fontView.textStorage?.attribute(.font, at:0, effectiveRange:nil) as? NSFont
    require(importedFont?.familyName == "Verdana" && !NSFontManager.shared.traits(of: importedFont ?? NSFont.systemFont(ofSize:12)).contains(.boldFontMask), "editor HTML uses an explicit regular sans-serif default rather than a Times fallback")
    let replyDocument = ComposeDocument.reply(source: detail, body: "My answer")
    require(replyDocument.contains("发件人：") && replyDocument.contains("收件人：") && replyDocument.contains("日期：") && replyDocument.contains("主题："), "reply quotation includes original message metadata")
    let replyEditor = EditorHandle()
    replyEditor.loadHTML(replyDocument)
    require(replyEditor.plainText().contains("Cached body") && replyEditor.plainText().contains("My answer"), "HTML reply body and original quotation survive pre-attachment initialization")
    require(replyEditor.insertAutomaticSignature("<b>Example Signature</b>", beforeQuote: true), "default signature can be inserted before editor mounts")
    let initialReply = replyEditor.plainText() as NSString
    require(initialReply.range(of:"My answer").location < initialReply.range(of:"Example Signature").location && initialReply.range(of:"Example Signature").location < initialReply.range(of:ComposeDocument.quoteMarker).location, "reply order is answer then signature then original message")
    let mountedReply = NSTextView()
    replyEditor.attach(mountedReply)
    mountedReply.textStorage?.insert(NSAttributedString(string:"Typing now\n"), at:0)
    mountedReply.setSelectedRange(NSRange(location:5,length:0))
    require(replyEditor.insertAutomaticSignature("<p>Late signature</p>", beforeQuote:true) && mountedReply.string.hasPrefix("Typing now") && mountedReply.selectedRange().location == 5, "async signature insertion preserves user input and caret")
    replyEditor.attach(mountedReply)
    require(mountedReply.string.hasPrefix("Typing now"), "repeated attachment does not replay stale initial body")
    let emptyEditor = EditorHandle()
    emptyEditor.setText("User removed the quote")
    require(!emptyEditor.insertAutomaticSignature("<p>Signature</p>",beforeQuote:true) && emptyEditor.plainText() == "User removed the quote", "automatic signature does not guess when user deleted quote marker")
    var styledDraft = MailDraft(accountID: a.id, from: "own@example.test", mode: "reply", source: detail)
    require((try? JSONDecoder().decode(MailDraft.self, from: JSONEncoder().encode(styledDraft)))?.priority == nil, "older draft schema without priority remains readable")
    styledDraft.priority = 1
    styledDraft.rtf = replyEditor.rtfData()
    let restoredDraft = try? JSONDecoder().decode(MailDraft.self, from: JSONEncoder().encode(styledDraft))
    require(restoredDraft?.priority == 1 && restoredDraft?.rtf != nil, "rich reply and priority survive draft roundtrip")
    let testState = AppState(fixture: true)
    testState.preferences.value.autoBccMyself = true
    testState.preferences.value.defaultBccAddress = "global@example.test"
    testState.preferences.value.defaultBccByAccount = [a.id: "acc@example.test"]
    let computedBcc = testState.defaultBcc(for: a.id, from: "sender@example.test")
    require(computedBcc.contains("sender@example.test") && computedBcc.contains("global@example.test") && computedBcc.contains("acc@example.test"), "defaultBcc computes autoBcc myself, account bcc, and global bcc")
    testState.preferences.value.autoBccMyself = false
    let bccWithoutSelf = testState.defaultBcc(for: a.id, from: "sender@example.test")
    require(!bccWithoutSelf.contains("sender@example.test") && bccWithoutSelf.contains("global@example.test"), "defaultBcc omits sender when autoBccMyself is disabled")
    var draftWithBcc = MailDraft(accountID: a.id, from: "sender@example.test", mode: "new")
    draftWithBcc.bcc = testState.defaultBcc(for: a.id, from: "sender@example.test")
    let composeModel = ComposeModel(state: testState, draft: draftWithBcc)
    require(composeModel.showBcc && composeModel.bcc.contains("global@example.test"), "compose model displays bcc row when default bcc present")
    runMailSyncPolicyTests { condition, label in require(condition, label) }
    runMailUnreadCounterTests { condition, label in require(condition, label) }
    runComposeFormattingTests { condition, label in require(condition, label) }
    try? FileManager.default.removeItem(at:temp)
    print("PASS: \(checks) native model, cache persistence/isolation, outbox queue, preferences migration, action payloads, body HTML, reply identity, cookie scope and trust checks.")
}
